long type_monster_data::take_damage(long damage)
{
    if (total_hit_points < damage) {
        damage = total_hit_points;
        total_hit_points = 0;
        count = 0;
    } else {
        total_hit_points -= damage;
        count = (total_hit_points + hit_points - 1) / hit_points;
    }
    return damage;
}

