                defeatedHero->remove_artifact(ARTIFACT_HOLY_GRAIL);
            if (!surrendered && defeatedHero)
                defeatedHero->TransferArtifacts(my_hero);

            if (enemy_town)
                gpGame->ClaimTown(enemy_town->id, my_hero->owner, 0, 1);
